export const TOPIC_IDS: ReadonlySet<string> = new Set(TOPICS.map((t) => t.id));

const BY_ID = new Map(TOPICS.map((t) => [t.id, t]));

/**
 * browseReels' own ceiling on `filters.tags`, restated here so this module can
 * respect it rather than be truncated by it. Keep the two in step.
 */
const BROWSE_TAG_LIMIT = 12;

/**
 * Turn the selected topic id into the flat tag list browseReels wants.
 *
 * Written for a list because the route hands one in, but normalizeTopics caps
 * that list at one entry, so in practice this returns exactly one topic's twelve
 * tags and the chip's printed count is exactly what the wall comes back with.
 *
 * The round-robin below is what keeps it honest if the cap is ever raised. Laid
 * end to end, two topics would be 24 tags and browseReels would keep the first
 * 12, so the second chip would contribute nothing at all and "comedy + food"
 * would return precisely the comedy reels. Interleaved, both are represented.
 * Neither arrangement is correct while the ceiling is 12, which is why the cap
 * is 1; see MAX_SELECTED in build_topics.py for the measured numbers.
 */
export function tagsForTopics(ids: string[]): string[] {
  const lists = ids.map((id) => BY_ID.get(id)?.tags ?? []).filter((t) => t.length);
  const out: string[] = [];
  const seen = new Set<string>();
  const deepest = Math.max(0, ...lists.map((l) => l.length));
  for (let rank = 0; rank < deepest && out.length < BROWSE_TAG_LIMIT; rank += 1) {
    for (const list of lists) {
      if (out.length === BROWSE_TAG_LIMIT) break;
      const tag = list[rank];
      if (!tag || seen.has(tag)) continue;
      seen.add(tag);
      out.push(tag);
    }
  }
  return out;
}

/**
 * Clamp an untrusted list of ids down to the ones that exist.
 *
 * Accepts the comma-joined form the URL carries as well as a real array, since
 * `?topics=comedy,food` is what a shared link looks like.
 *
 * Capped at 1, because every extra id widens the PostgREST array literal the
 * browse query sends, and a request naming forty topics is someone probing the
 * endpoint rather than someone filtering reels.
 */
export function normalizeTopics(raw: unknown): string[] {
  const parts =
    typeof raw === "string"
      ? raw.split(",")
      : Array.isArray(raw)
        ? raw.map((v) => (typeof v === "string" ? v : ""))
        : [];
  const out: string[] = [];
  for (const part of parts) {
    const id = part.trim().toLowerCase();
    if (!TOPIC_IDS.has(id) || out.includes(id)) continue;
    out.push(id);
    if (out.length === 1) break;
  }
  return out;
}
